// Request identifiers are generated by the server, never supplied by callers.
// Accept its random ID and its entropy-failure fallback; reject arbitrary text.
export function validRequestId(value: unknown): string | undefined {
  return typeof value === 'string' && /^(?:[0-9a-f]{32}|[0-9a-f]{1,16}-[0-9a-f]{1,16})(?![\s\S])/u.test(value) ? value : undefined
}

