function errorMessage(status: number, code: string): string {
  return Object.hasOwn(errorMessages, code) ? errorMessages[code]! : status >= 500 ? '服务器暂时出了问题，请稍后重试。' : '请求未能完成，请刷新后重试。'
}

export class APIError extends Error {
  readonly status: number
  readonly code: string
  readonly shortfallBytes?: number
  readonly requestId?: string

  constructor(status: number, code: string, shortfallBytes?: number, requestId?: string) {
    const safeCode = /^[a-z][a-z0-9_]{0,63}(?![\s\S])/u.test(code) ? code : 'request_failed'
    super(errorMessage(status, safeCode))
    this.name = 'APIError'
    this.status = status
    this.code = safeCode
    this.shortfallBytes = shortfallBytes
    this.requestId = validRequestId(requestId)
  }
}

export async function parseAPIError(response: Response): Promise<APIError> {
  let code = 'request_failed', shortfallBytes: number | undefined
  const headerId = validRequestId(response.headers.get('X-Request-ID'))
  let requestId = headerId
  try {
    const value: unknown = await response.json()
    if (value && typeof value === 'object' && !Array.isArray(value)) {
      const body = value as Record<string, unknown>
      if (typeof body.error === 'string') code = body.error
      if (Number.isSafeInteger(body.shortfallBytes) && Number(body.shortfallBytes) >= 0) shortfallBytes = Number(body.shortfallBytes)
      if ('requestId' in body) {
        const bodyId = validRequestId(body.requestId)
        // Never associate an error with an unrelated header/body identifier.
        requestId = bodyId && (!headerId || bodyId === headerId) ? bodyId : undefined
      }
    }
  } catch {
    // Non-JSON proxy errors still carry a usable server header, when present.
  }
  return new APIError(response.status, code, shortfallBytes, requestId)
}
